<template>
	<view class="container">
		<u-loading-page :loading="true" v-if="load" fontSize="28rpx" />
		<block v-else>
			<view class="map-container">
				<map
				scale="14"
				:latitude="art.latitude" 
				:longitude="art.longitude"
				:markers="markers"
				class="map"/>
			</view>
		<scroll-view scroll-y="true" class="scroll">
			<view class="info">
				<view class="tit-text">{{art.gs_name}}</view>
				<view class="title-text">
					<text>公司位置</text>
					<button size="mini" class="dh-btn" @click="goClick">
						<image src="@/static/index/dh-icon.png" mode="widthFix"></image>
						<text>导航</text>
					</button>
				</view>
				<view class="info-items">
					<view class="info-item">
						<text class="left-text">具体位置</text>
						<text class="right-text">{{art.address}}</text>
					</view>
				</view>
				<view class="content">
					<view class="title-text">联系我们</view>
					<view class="content-text">
						<view class="info-item">
							<text class="left-text">联系电话</text>
							<view class="right-text">
								<text class="phone-text" @click="call_phone(art.phone)">{{art.phone}}</text>
								<text class="bd-text">(点击拨打)</text>
							</view>
						</view>
					</view>
				</view>
			</view>
		</scroll-view>
		</block>
	</view>
</template>

<script>
	var _this;
	export default {
		data() {
			return {
				art:{},
				markers:[]
			}
		},
		onLoad(e) {
			_this = this;
			this.get_wz_xq()
		},
		methods: {
			async get_wz_xq() {
				const params = {
					id:4,
					is_http:1,
				}
				const data = await _this.$post('port/xieyi_xq', params)
				if (data.code == 200) {
					_this.art = data.result.art
					_this.markers = [
						{
							// 'id':1,
							'latitude':_this.art.latitude,
							'longitude':_this.art.longitude,
							'iconPath':'/static/common/gongsi.png',
							'width':40,
							'height':45,
						}
					]
				} else {
					this.$u.toast(data.msg)
				}
				if (_this.load) {
					_this.load = false
				}
			},
			goClick(){
				 let item = this.art
				//跳转到导航页面
				uni.openLocation({
					latitude:parseFloat(item.latitude),
					longitude:parseFloat(item.longitude),
					name:item.gs_name,
					address:`${item.address}`,
					success(res) {
						console.log(res);
					},
					fail(fail) {
						console.log(fail);
					}
				})
			}
		}
	}
</script>

